#include "correlation.h"
#include <math.h>

void kernel_correlation(double float_n, double data[32][28], double corr[28][28], double mean[28], double stddev[28]) {
    double normalized[32][28];

    // compute mean for each attribute
    for (int j = 0; j < 28; j++) {
        double sum = 0.0;
        for (int i = 0; i < 32; i++) {
            sum += data[i][j];
        }
        mean[j] = sum / float_n;
    }

    // compute standard deviation and normalize data
    for (int j = 0; j < 28; j++) {
        double diff;
        double sum_sq = 0.0;

        for (int i = 0; i < 32; i++) {
            diff = data[i][j] - mean[j];
            sum_sq += diff * diff;
        }
        stddev[j] = sqrt(sum_sq / float_n);

        for (int i = 0; i < 32; i++) {
            diff = data[i][j] - mean[j];
            if (stddev[j] != 0.0) {
                normalized[i][j] = diff / stddev[j];
            } else {
                normalized[i][j] = 0.0;
            }
        }
    }

    // compute correlation coefficients
    for (int i = 0; i < 28; i++) {
        for (int j = 0; j < 28; j++) {
            double sum = 0.0;
            for (int k = 0; k < 32; k++) {
                sum += normalized[k][i] * normalized[k][j];
            }
            corr[i][j] = sum / float_n;
        }
    }
}

